export const usePlatformConfig = () => {
  return useQuery({
    queryKey: ["platform_config"],
    queryFn: async (): Promise<PlatformConfig> => {
      // Uses the get_public_platform_config() SECURITY DEFINER function which
      // returns only non-sensitive columns. Direct table SELECT is now
      // restricted to admins only (platform_config RLS migration 20260324120000).
      const { data, error } = await (supabase as any).rpc("get_public_platform_config");
      if (error || !data || !data[0]) return DEFAULTS;
      return data[0] as PlatformConfig;
    },
    retry: false,
    placeholderData: DEFAULTS,
  });
};

